var timer = null;

// ---------- pieces ----------

function isType(t) { return TYPES.indexOf(t) !== -1; }

function randomType() {
  if (state.bag.length === 0) {
    var bag = TYPES.slice();
    for (var i = bag.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = bag[i]; bag[i] = bag[j]; bag[j] = tmp;
    }
    state.bag = bag;
  }
  return state.bag.pop();
}

function cleanQueue(queue) {
  if (!Array.isArray(queue)) return [];
  return queue.map(function (t) { return String(t).toUpperCase(); }).filter(isType);
}

function fillPreview() {
  while (state.next.length < PREVIEW) state.next.push(randomType());
}

function makeMatrix(type) {
  return SHAPES[type].map(function (r) { return r.split(""); });
}

function pieceCells(piece) {
  var cells = [];
  for (var r = 0; r < piece.matrix.length; r++) {
    for (var c = 0; c < piece.matrix[r].length; c++) {
      if (piece.matrix[r][c] !== ".") cells.push([piece.row + r, piece.col + c]);
    }
  }
  return cells;
}

function fits(matrix, row, col) {
  for (var r = 0; r < matrix.length; r++) {
    for (var c = 0; c < matrix[r].length; c++) {
      if (matrix[r][c] === ".") continue;
      var br = row + r, bc = col + c;
      if (br < 0 || br >= ROWS || bc < 0 || bc >= COLS) return false;
      if (state.board[br][bc] !== ".") return false;
    }
  }
  return true;
}

// [REQ-001] [REQ-004] Spawn the next piece; the game ends if it has nowhere to go.
function spawn() {
  var type = state.next.length ? state.next.shift() : randomType();
  fillPreview();
  var matrix = makeMatrix(type);
  var top = 0;
  while (matrix[top].every(function (ch) { return ch === "."; })) top++;
  var piece = {
    type: type,
    matrix: matrix,
    row: -top,
    col: Math.floor((COLS - matrix[0].length) / 2),
    lockTicks: 0,
    lockResets: 0
  };
  if (!fits(piece.matrix, piece.row, piece.col)) {
    state.current = null;
    state.status = "gameover";
    stopTimer();
    return;
  }
  state.current = piece;
}

// ---------- core rules ----------

// [REQ-003] Remove full rows, drop the rest, score by rows cleared at once times level.
function clearLines() {
  var kept = state.board.filter(function (row) {
    return row.some(function (ch) { return ch === "."; });
  });
  var cleared = ROWS - kept.length;
  while (kept.length < ROWS) kept.unshift(emptyRow());
  state.board = kept;
  if (cleared > 0) {
    state.score += LINE_POINTS[cleared] * state.level;
    state.lines += cleared;
    state.level = Math.floor(state.lines / 10) + 1;
  }
}

// [REQ-001] Lock the falling piece into the board, clear lines, spawn the next one.
function lockPiece() {
  var p = state.current;
  pieceCells(p).forEach(function (cell) {
    state.board[cell[0]][cell[1]] = p.type;
  });
  state.current = null;
  clearLines();
  spawn();
}

function tryMove(dr, dc) {
  var p = state.current;
  if (!p || !fits(p.matrix, p.row + dr, p.col + dc)) return false;
  p.row += dr;
  p.col += dc;
  return true;
}

// Lock rule (DEC): a gravity step that cannot move the piece down counts one tick of
// lock delay; the piece locks on the LOCK_DELAY-th such tick. A left/right move while
// resting restarts the delay, at most MAX_LOCK_RESETS times per piece.
var LOCK_DELAY = 2;
var MAX_LOCK_RESETS = 3;

function isResting(p) {
  return !fits(p.matrix, p.row + 1, p.col);
}

// [REQ-002] One gravity step: fall one row, or count a tick of lock delay.
// Used by the real timer, by tick(n) and by soft drop. Returns true if the piece fell.
function gravityStep() {
  if (state.status !== "running" || !state.current) return false;
  var p = state.current;
  if (tryMove(1, 0)) {
    p.lockTicks = 0;
    return true;
  }
  p.lockTicks++;
  if (p.lockTicks >= LOCK_DELAY) lockPiece();
  return false;
}

// [REQ-002] Sideways move; restarts the lock delay if the piece was resting.
function shift(dc) {
  var p = state.current;
  var resting = isResting(p);
  if (!tryMove(0, dc)) return;
  if (resting && p.lockResets < MAX_LOCK_RESETS) {
    p.lockResets++;
    p.lockTicks = 0;
  }
}

// [REQ-002] Clockwise rotation with sideways kicks; refused if nothing fits.
function rotate() {
  var p = state.current;
  if (!p) return;
  var size = p.matrix.length;
  var rotated = [];
  for (var r = 0; r < size; r++) {
    rotated.push([]);
    for (var c = 0; c < size; c++) rotated[r].push(p.matrix[size - 1 - c][r]);
  }
  var kicks = [0, -1, 1, -2, 2];
  for (var i = 0; i < kicks.length; i++) {
    if (fits(rotated, p.row, p.col + kicks[i])) {
      p.matrix = rotated;
      p.col += kicks[i];
      return;
    }
  }
}

// [REQ-001] [REQ-003] Player actions; soft and hard drop score per cell moved down.
function input(action) {
  if (state.status !== "running" || !state.current) return;
  switch (action) {
    case "left": shift(-1); break;
    case "right": shift(1); break;
    case "softDrop":
      if (gravityStep()) state.score += SOFT_DROP_POINTS;
      break;
    case "hardDrop":
      var dropped = 0;
      while (tryMove(1, 0)) dropped++;
      state.score += dropped * HARD_DROP_POINTS;
      lockPiece();
      break;
    case "rotate":
    case "rotateCW": rotate(); break;
    default: return;
  }
  render();
  restartTimerIfNeeded();
}

// ---------- timer ----------

function gravityInterval() {
  return Math.max(100, 1000 - (state.level - 1) * 90);
}

function stopTimer() {
  if (timer !== null) { clearTimeout(timer); timer = null; }
}

function startTimer() {
  stopTimer();
  if (state.status !== "running") return;
  timer = setTimeout(function () {
    timer = null;
    gravityStep();
    render();
    startTimer();
  }, gravityInterval());
}

function restartTimerIfNeeded() {
  if (state.status === "running" && timer === null) startTimer();
}

// ---------- setup ----------

function emptyRow() {
  var row = [];
  for (var c = 0; c < COLS; c++) row.push(".");
  return row;
}

// [REQ-001] Start a fresh game, optionally with a fixed piece order.
function newGame(queue) {
  state.board = [];
  for (var r = 0; r < ROWS; r++) state.board.push(emptyRow());
  state.bag = [];
  state.score = 0;
  state.level = 1;
  state.lines = 0;
  state.status = "running";
  state.current = null;
  state.next = cleanQueue(queue);
  fillPreview();
  spawn();

